import React, { FC, forwardRef, ReactNode } from 'react';
import { getCurrencySymbol } from '@fiverr-private/localization';
import { type Types } from '@fiverr-private/theme';
import NumberInput from '../NumberInput';
import InputGroup from '../Input/InputGroup';
import InputPrefix from '../Input/InputPrefix';

type OmittedProps = 'type' | 'value' | 'children';
interface CurrencyInputProps
  extends Omit<React.ComponentProps<typeof InputGroup>, OmittedProps>,
    Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'> {
  currencyCode?: string;
  /** Optional - by default uses locale from context */
  formattingLocale?: string;
  value?: number | undefined;
  children?: ReactNode;
  hideNumberSpinButton?: boolean;

  /** Whether to disable the arrow keys from changing the value */
  disableArrowKeysOnChange?: boolean;
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  /**
   * By default, `minimumFractionDigits` is ignored for integers.
   * Set this to `false` to show trailing zeros for integers, e.g. 10.00.
   */
  stripTrailingZerosIfInteger?: boolean;
  min?: number;
  max?: number;
  id?: string;
}

const FALLBACK_SYMBOL = '$';

const CurrencyInput: FC<CurrencyInputProps> = forwardRef<HTMLInputElement, CurrencyInputProps>(
  (
    {
      currencyCode = 'USD',
      formattingLocale,
      onChange,
      children,
      minimumFractionDigits = 2,
      maximumFractionDigits = 2,
      stripTrailingZerosIfInteger = true,
      id,
      dataTrackTag = 'currency_input',
      dataTrackValue,
      ...restProps
    },
    ref
  ) => {
    const getCurrencySymbolInner = () => {
      try {
        return getCurrencySymbol({ currencyCode, formattingLocale });
      } catch (e) {
        // This is mostly for storybook, so the component doesn't crash while typing in the currencyCode prop
        return FALLBACK_SYMBOL;
      }
    };

    const currencySymbol = getCurrencySymbolInner();

    return (
      <InputGroup ref={ref} dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue} {...restProps}>
        <NumberInput
          id={id}
          onChange={onChange}
          minimumFractionDigits={minimumFractionDigits}
          maximumFractionDigits={maximumFractionDigits}
          stripTrailingZerosIfInteger={stripTrailingZerosIfInteger}
        />
        <InputPrefix>{currencySymbol}</InputPrefix>
        {children}
      </InputGroup>
    );
  }
);

CurrencyInput.displayName = 'CurrencyInput';

export default CurrencyInput;
