import React, { FC, forwardRef, useCallback, useImperativeHandle, useMemo, useRef } from 'react';
import { isNaN, isNil, isNull, isUndefined, range, round } from 'lodash';
import { type Types } from '@fiverr-private/theme';
import Input from '../Input';
import { INPUT_ID } from '../Input/constants';
import { triggerOnChange } from './utils';

type OmittedProps = 'type' | 'value' | 'defaultValue';
interface NumberInputProps
  extends Omit<React.ComponentProps<typeof Input>, OmittedProps>,
    Pick<Types.BoxType, 'dataTrackTag' | 'dataTrackValue'> {
  value?: number | null;
  defaultValue?: number | undefined;
  hideNumberSpinButton?: boolean;

  /** Whether to disable the arrow keys from changing the value */
  disableArrowKeysOnChange?: boolean;
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
  /**
   * By default, `minimumFractionDigits` is ignored for integers.
   * Set this to `false` to show trailing zeros for integers, e.g. 10.00.
   */
  stripTrailingZerosIfInteger?: boolean;
  min?: number;
  max?: number;
}

const ALLOWED_CHARACTERS = range(10).map(String);

const NumberInput: FC<NumberInputProps> = forwardRef<HTMLInputElement, NumberInputProps>(
  (
    {
      min,
      onChange,
      onBlur,
      onKeyDown,
      onPaste,
      minimumFractionDigits = 0,
      maximumFractionDigits = Infinity,
      disableArrowKeysOnChange = false,
      stripTrailingZerosIfInteger = true,
      dataTrackTag = 'number_input',
      ...props
    },
    ref
  ) => {
    const localRef = useRef<HTMLInputElement>(null);
    useImperativeHandle(ref, () => localRef.current as HTMLInputElement);

    const allowedCharacters = useMemo(() => {
      const keys = [...ALLOWED_CHARACTERS];

      if (maximumFractionDigits > 0) {
        keys.push('.');
      }

      if (min === undefined || Number(min) < 0) {
        keys.push('-');
      }

      return keys;
    }, [min, maximumFractionDigits]);

    const prohibitedRegex = useMemo(() => new RegExp(`[^${allowedCharacters.join('')}]`, 'g'), [allowedCharacters]);

    const sanitizeValue = useCallback(
      (stringValue) => {
        let sanitizedValue = stringValue.replace(prohibitedRegex, '');

        const [wholePart, fractionalPart] = sanitizedValue.split('.');

        if (fractionalPart?.length > maximumFractionDigits) {
          sanitizedValue = `${wholePart}.${fractionalPart.slice(0, maximumFractionDigits)}`;
        }

        return sanitizedValue;
      },
      [prohibitedRegex, maximumFractionDigits]
    );

    const formatValue = useCallback(
      (numberValue: number | undefined | null): string | undefined => {
        if (isNaN(numberValue) || isNull(numberValue)) {
          return '';
        }

        if (isUndefined(numberValue)) {
          return undefined;
        }

        const roundedValue = round(numberValue, maximumFractionDigits);
        const [, fractionalPart] = roundedValue.toString().split('.');
        const originalFractionDigits = fractionalPart?.length || 0;
        const isInteger = originalFractionDigits === 0;
        const fractionDigits =
          isInteger && stripTrailingZerosIfInteger ? 0 : Math.max(minimumFractionDigits, originalFractionDigits);

        return roundedValue.toFixed(fractionDigits);
      },
      [minimumFractionDigits, maximumFractionDigits, stripTrailingZerosIfInteger]
    );

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
      const isArrowKey = ['ArrowUp', 'ArrowDown'].includes(e.key);
      const isChar = e.key.length === 1;
      const isModifierKey = e.ctrlKey || e.metaKey || e.altKey;
      const shouldBlockArrowKey = disableArrowKeysOnChange && isArrowKey;
      const shouldBlockChar = isChar && !isModifierKey && !allowedCharacters.includes(e.key);

      if (shouldBlockArrowKey || shouldBlockChar) {
        e.preventDefault();
        return;
      }

      onKeyDown?.(e);
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const sanitizedValue = sanitizeValue(e.currentTarget.value);

      if (sanitizedValue !== e.currentTarget.value) {
        e.preventDefault();
        triggerOnChange(e.currentTarget, sanitizedValue);
        return;
      }

      onChange?.(e);
    };

    const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
      const { currentTarget } = e;
      onPaste?.(e);

      setTimeout(() => {
        if (!currentTarget) {
          return;
        }

        const sanitizedValue = sanitizeValue(currentTarget.value);
        triggerOnChange(currentTarget, sanitizedValue);
      });
    };

    const handleWheel = (e: React.WheelEvent<HTMLInputElement>) => {
      const element = e.currentTarget;
      const isFocused = document.activeElement === element;

      if (isFocused) {
        element.blur();
      }
    };

    const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
      const { currentTarget } = e;
      const { valueAsNumber } = currentTarget;
      const formattedValue = formatValue(valueAsNumber);

      triggerOnChange(currentTarget, formattedValue);
      onBlur?.(e);
    };

    const formattedValue = useMemo(() => formatValue(props.value), [props.value, formatValue]);
    const formattedDefaultValue = useMemo(() => formatValue(props.defaultValue), [props.defaultValue, formatValue]);

    // To ensure we don't strip trailing zeros while the user is typing,
    // we'll defer formatting while the input is focused.
    const isFocused = typeof document !== 'undefined' && document.activeElement === localRef.current;
    const displayValue = isFocused && !isNil(props.value) && !isNaN(props.value) ? props.value : formattedValue;

    return (
      <Input
        {...props}
        ref={localRef}
        type="number"
        value={displayValue}
        defaultValue={formattedDefaultValue}
        min={min}
        onChange={handleChange}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
        onPaste={handlePaste}
        onWheel={handleWheel}
        inputMode={maximumFractionDigits > 0 ? 'decimal' : 'numeric'}
        dataTrackTag={dataTrackTag}
      />
    );
  }
);

NumberInput.displayName = 'NumberInput';

Object.assign(NumberInput, {
  id: INPUT_ID,
});

export default NumberInput;
